package ru.murad.yourmarket.service;import lombok.RequiredArgsConstructor;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import ru.murad.yourmarket.model.enums.AdvertisementStatus;import ru.murad.yourmarket.repository.AdvertisementRepository;import java.time.Instant;
@Component @RequiredArgsConstructor public class PublicationRecoveryScheduler {private final AdvertisementRepository repository;private final PublicationTransactionService transactions;@Scheduled(fixedDelayString="${publication.recovery-delay-ms:60000}")public void recover(){repository.findTop100ByStatusAndPublicationUpdatedAtLessThanEqualOrderByPublicationUpdatedAtAsc(AdvertisementStatus.PUBLICATION_IN_PROGRESS,Instant.now().minusSeconds(120)).forEach(a->transactions.recoverStale(a.getId()));}}
